let fileContent = msg.payload;

let defaultResponse = {
    actionBio: "no collection",
    colorBio: "white",
    actionPaper: "no collection",
    colorPaper: "white",
    actionDomestic: "no collection",
    colorDomestic: "white"
};

if (!fileContent || typeof fileContent !== 'string') {
    node.status({ fill: "red", shape: "ring", text: "Invalid file content" });
    flow.set('boxStatus', defaultResponse);
    msg.payload = { ledPower: 0, status: defaultResponse };
    return msg;
}

let lines = fileContent.split(/\r?\n/);
let events = [];
let currentEvent = null;

for (let line of lines) {
    if (line.startsWith('BEGIN:VEVENT')) {
        currentEvent = {};
    } else if (line.startsWith('END:VEVENT') && currentEvent) {
        events.push(currentEvent);
        currentEvent = null;
    } else if (currentEvent) {
        let splitIdx = line.indexOf(':');
        if (splitIdx !== -1) {
            let key = line.substring(0, splitIdx).trim();
            let val = line.substring(splitIdx + 1).trim();
            currentEvent[key] = val;
        }
    }
}

let tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);
let year = tomorrow.getFullYear();
let month = String(tomorrow.getMonth() + 1).padStart(2, '0');
let day = String(tomorrow.getDate()).padStart(2, '0');
let tomorrowStr = `${year}${month}${day}`;

let upcomingEvents = events.filter(ev => {
    let dtStart = "";
    if (ev.DTSTART) {
        if (ev.DTSTART.includes(':')) {
            dtStart = ev.DTSTART.split(':').pop().trim();
        } else {
            dtStart = ev.DTSTART.split('T')[0];
        }
    }
    return dtStart === tomorrowStr;
});

let activeResponse = { ...defaultResponse };
let ledState = 0;

if (upcomingEvents.length > 0) {
    ledState = 1;
    node.status({ fill: "green", shape: "dot", text: `Morgen Abholung! (${upcomingEvents.length})` });

    for (let ev of upcomingEvents) {
        let summary = (ev.SUMMARY || "").toLowerCase();

        if (summary.includes('biomüll') || summary.includes('bio')) {
            activeResponse.actionBio = "take out the trash - biomüll";
            activeResponse.colorBio = "green";
        }
        if (summary.includes('papier')) {
            activeResponse.actionPaper = "take out the trash - papier";
            activeResponse.colorPaper = "yellow";
        }
        if (summary.includes('restmüll')) {
            activeResponse.actionDomestic = "take out the trash - restmüll";
            activeResponse.colorDomestic = "red";
        }
    }
} else {
    node.status({ fill: "yellow", shape: "ring", text: "Keine Abholung morgen" });
    ledState = 0;
}

flow.set('boxStatus', activeResponse);

msg.payload = {
    ledPower: ledState,
    status: activeResponse
};
return msg;

let data = msg.payload.status || {};
let activeLEDColor = "blue"; // Default to blue exclusively for no trash
let targetDescription = "No trash scheduled for tomorrow (Blue LED)";

if (data.colorBio === "green") {
    activeLEDColor = "green";
    targetDescription = "Target: Biomüll (Green LED)";
} else if (data.colorPaper === "yellow") {
    activeLEDColor = "yellow";
    targetDescription = "Target: Papier (Yellow LED)";
} else if (data.colorDomestic === "red") {
    activeLEDColor = "red";
    targetDescription = "Target: Restmüll (Red LED)";
}

msg.payload = {
    simulationTarget: targetDescription,
    simulatedLedColor: activeLEDColor,
    timestamp: new Date().toISOString()
};

return msg;

let reqBody = msg.payload || {};

let isReset = reqBody.reset === true || 
              reqBody.action === "reset" || 
              reqBody.color === "white" ||
              reqBody.status === "white";

let currentStatus = flow.get('boxStatus') || {
    actionBio: "no collection",
    colorBio: "white",
    actionPaper: "no collection",
    colorPaper: "white",
    actionDomestic: "no collection",
    colorDomestic: "white"
};

if (isReset) {
    node.status({ fill: "grey", shape: "ring", text: "Reset requested" });

    currentStatus = {
        actionBio: "no collection",
        colorBio: "white",
        actionPaper: "no collection",
        colorPaper: "white",
        actionDomestic: "no collection",
        colorDomestic: "white"
    };

    flow.set('boxStatus', currentStatus);
} else {
    node.status({ fill: "blue", shape: "dot", text: "Serving current box status" });
}

msg.payload = currentStatus;
return msg;
